def bounding_box(points):
    x = y = 0
    nx = ny = 0
    for p in points:
        x, y = p
        if not x:
            x = 0
            nx = 0
        elif x < 0:
            nx = min(nx, x)
        elif x > 0:
            nx = max(nx, x)
        if not y:
            y = 0
            ny = 0
        elif y < 0:
            ny = min(ny, y)
        elif y > 0:
            ny = max(ny, y)
    return (nx, ny, nx, ny)
